pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    if arr.len() <= 1 { return; }
    let depth = (2.0 * (arr.len() as f64).log2()) as usize;
    introsort(arr, depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], depth: usize) {
    let n = arr.len();
    if n <= 16 {
        for i in 1..n {
            let mut j = i;
            while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
        }
        return;
    }
    if depth == 0 { arr.sort_unstable(); return; }
    // Median-of-three pivot
    let (lo, mid, hi) = (0, n / 2, n - 1);
    if arr[mid] < arr[lo] { arr.swap(lo, mid); }
    if arr[hi] < arr[lo] { arr.swap(lo, hi); }
    if arr[mid] < arr[hi] { arr.swap(mid, hi); }
    let pivot = arr[hi].clone();
    let mut i = 0;
    for j in 0..hi {
        if arr[j] <= pivot { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, hi);
    introsort(&mut arr[..i], depth - 1);
    if i + 1 < n { introsort(&mut arr[i + 1..], depth - 1); }
}
